import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const f=JSON.parse('{"title":"Tailoring","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/tailoring.md","filePath":"en/guide/professions/tailoring.md"}'),o={name:"en/guide/professions/tailoring.md"};function n(l,a,s,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="tailoring" tabindex="-1">Tailoring <a class="header-anchor" href="#tailoring" aria-label="Permalink to &quot;Tailoring&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Work leather, cloth, fibers and padding into clothing and flexible protection.</li><li>Fitting, stitching and repairs give tailoring value during expeditions.</li><li>Function, fashion and material knowledge are all paths to reputation.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Prepare materials</td><td>Harvest, preserve, process and grade hides or fibers.</td></tr><tr><td>Make and fit</td><td>Cut, assemble, fit and finish garments or flexible armor.</td></tr><tr><td>Build knowledge</td><td>A Material/Tailoring Journal records treatments, construction and styles.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Cloth and leather become clothing and armor through crafting.</td><td>Preservation, processing and fitting become meaningful craft choices.</td></tr><tr><td>Clothes, dyes and leather armor already offer identity and protection.</td><td>Material treatment and maintenance deepen these roles without a flat armor bonus.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/tailoring/" target="_blank" rel="noreferrer">Tailoring</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An expedition tailor could stitch and refit damaged leather equipment. A fashion specialist might instead become known for a distinctive guild cut or embroidery.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Damage to a creature may affect its hide. Anatomy and Animal Lore could inform harvesting; a separate skinning skill is undecided.</li><li>Flexible protection should differ from plate. Harvesting, fitting and layering rules remain open; Alchemy may supply treatments and dyes.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/guide/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/tailoring.html">Tailoring</a></p>',18)])])}const m=e(o,[["render",n]]);export{f as __pageData,m as default};
